#[track_caller]
pub fn deadline(&self, key: &Key) -> Instant {
    self.start + Duration::from_millis(self.slab[*key].when)
}

/// Removes the key from the expired queue or the timer wheel
/// depending on its expiration status.
///
/// # Panics
///
/// Panics if the key is not contained in the expired queue or the wheel.
#[track_caller]
fn remove_key(&mut self, key: &Key) {
    use crate::time::wheel::Stack;

    // Special case the `expired` queue
    if self.slab[*key].expired {
        self.expired.remove(key, &mut self.slab);
    } else {
        self.wheel.remove(key, &mut self.slab);
    }
}

/// Removes the item associated with `key` from the queue.
///
/// There must be an item associated with `key`. The function returns the
/// removed item as well as the `Instant` at which it will the delay will
/// have expired.
///
/// # Panics
///
/// The function panics if `key` is not contained by the queue.
///
/// # Examples
///
/// Basic usage
///
/// ```rust
/// use tokio_util::time::DelayQueue;
/// use std::time::Duration;
///
/// # #[tokio::main]
/// # async fn main() {
/// let mut delay_queue = DelayQueue::new();
/// let key = delay_queue.insert("foo", Duration::from_secs(5));
///
/// // Remove the entry
/// let item = delay_queue.remove(&key);
/// assert_eq!(*item.get_ref(), "foo");
/// # }
/// ```
#[track_caller]
pub fn remove(&mut self, key: &Key) -> Expired<T> {
    let prev_poll_at = self.wheel.poll_at();
    let prev_deadline = match prev_poll_at {
        Some(poll_at) => {
            let poll_duration = Duration::from_millis(poll_at);
            let poll_ms = crate::time::ms(poll_duration, crate::time::Round::Down);
            Some(self.start + Duration::from_millis(poll_ms))
        }
        None => None,
    };

    let lookup_key = if self.slab.compact_called {
        match self.slab.key_map.get(key).copied() {
            Some(internal_key) => internal_key,
            None => panic!("Invalid index {}", key.index),
        }
    } else {
        (*key).into()
    };

    let entry_expired = self.slab.inner[lookup_key.index].expired;

    if entry_expired {
        let present = if self.slab.compact_called {
            match self.slab.key_map.get(key).copied() {
                Some(internal_key) => self.slab.inner.contains(internal_key.index),
                None => false,
            }
        } else {
            let internal_key = KeyInternal::from(*key);
            self.slab.inner.contains(internal_key.index)
        };

        assert!(present);

        debug_assert!({
            let mut next = self.expired.head;
            let mut contains = false;

            while let Some(idx) = next {
                let data = &self.slab[idx];

                if idx == *key {
                    debug_assert!(!contains);
                    contains = true;
                }

                next = data.next;
            }

            contains
        });

        let next_idx = self.slab[*key].next;
        let prev_idx = self.slab[*key].prev;

        if let Some(next) = next_idx {
            self.slab[next].prev = prev_idx;
        }

        if let Some(prev) = prev_idx {
            self.slab[prev].next = next_idx;
        } else {
            self.expired.head = next_idx;
        }

        self.slab[*key].next = None;
        self.slab[*key].prev = None;
    } else {
        let when = self.slab.inner[lookup_key.index].when;
        let elapsed = self.wheel.elapsed();

        assert!(
            elapsed <= when,
            "elapsed={}; when={}",
            elapsed,
            when
        );

        self.wheel.remove(key, &mut self.slab);
    }

    let remapped_key = if self.slab.compact_called {
        match self.slab.key_map.remove(key) {
            Some(key_internal) => key_internal,
            None => panic!("invalid key"),
        }
    } else {
        (*key).into()
    };

    let data = self.slab.inner.remove(remapped_key.index);

    let next_poll_at = self.wheel.poll_at();
    let next_deadline = match next_poll_at {
        Some(poll_at) => {
            let poll_duration = Duration::from_millis(poll_at);
